    async def create_sdk_token(
        self,
        *,
        vendor_data: str,
        ttl_seconds: int | NotGiven = NOT_GIVEN,
        max_uses: int | None | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> TransactionsCreateSdkTokenResponse:
        """Mint an SDK transaction token.

        Mint a short-lived scoped token your app passes to the Didit SDKs so they can submit transactions directly from the end-user's device via `POST /v1/transactions/`. The token is bound to one `vendor_data` (your user id): every transaction submitted with it has its subject identity enforced server-side from that binding, so a tampered client cannot submit on behalf of another user. Mint tokens from your backend - never ship the API key itself in an app. camelCase aliases (`vendorData`, `ttlSeconds`, `maxUses`) are also accepted.

        ``POST /v3/transactions/sdk-token/``

        Args:
          vendor_data: Your internal identifier for the end user this token is scoped to. Enforced as the subject identity of every transaction submitted with the token.
          ttl_seconds: Token lifetime in seconds. Defaults to 900 (15 minutes); maximum 86400 (24 hours).
          max_uses: Maximum number of successful submissions allowed with this token. Omit or null for unlimited uses within the TTL.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "TransactionsCreateSdkTokenResponse",
            await self._client.request(
                "post",
                "/v3/transactions/sdk-token/",
                cast_to=TransactionsCreateSdkTokenResponse,
                auth="api_key",
                body={"vendor_data": vendor_data, "ttl_seconds": ttl_seconds, "max_uses": max_uses},
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

